static string? ExtractConnectorToken(HttpContext httpContext, string payload)
{
    var token = httpContext.Request.Headers["X-Yeshua-Token"].FirstOrDefault()
        ?? httpContext.Request.Headers["Authorization"].FirstOrDefault()
        ?? httpContext.Request.Query["token"].FirstOrDefault();

    if (!string.IsNullOrWhiteSpace(token))
    {
        if (token.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
            token = token["Bearer ".Length..].Trim();

        return token.Trim();
    }

    if (string.IsNullOrWhiteSpace(payload))
        return null;

    try
    {
        var document = XDocument.Parse(payload, LoadOptions.PreserveWhitespace);
        var soapToken = document
            .Descendants()
            .FirstOrDefault(element =>
                string.Equals(element.Name.LocalName, "Token", StringComparison.OrdinalIgnoreCase) &&
                (element.Name.NamespaceName == "Token" || string.IsNullOrWhiteSpace(element.Name.NamespaceName)));

        return string.IsNullOrWhiteSpace(soapToken?.Value) ? null : soapToken.Value.Trim();
    }
    catch
    {
        return null;
    }
}

static async Task<string?> LoadConnectorWsdlAsync(IWebHostEnvironment env, string connectorKey, string serviceName, HttpContext httpContext)
{
    var wsdlPath = FindConnectorWsdlPath(env, connectorKey, serviceName);
    if (wsdlPath == null)
        return null;

    var wsdl = await File.ReadAllTextAsync(wsdlPath);
    return RewriteWsdlAddress(wsdl, httpContext);
}

static string? FindConnectorWsdlPath(IWebHostEnvironment env, string connectorKey, string serviceName)
{
    var basePath = Path.Combine(env.ContentRootPath, "Custon", "ExternalConnectors", connectorKey, serviceName);
    var candidates = new[]
    {
        Path.Combine(basePath, serviceName + ".single.wsdl"),
        Path.Combine(basePath, serviceName + ".wsdl"),
        Path.Combine(basePath, "service.single.wsdl"),
        Path.Combine(basePath, "service.wsdl")
    };

    return candidates.FirstOrDefault(File.Exists);
}

static string RewriteWsdlAddress(string wsdl, HttpContext httpContext)
{
    var scheme = httpContext.Request.Headers["X-Forwarded-Proto"].FirstOrDefault();
    if (string.IsNullOrWhiteSpace(scheme))
        scheme = httpContext.Request.Scheme;

    var host = httpContext.Request.Headers["X-Forwarded-Host"].FirstOrDefault();
    if (string.IsNullOrWhiteSpace(host))
        host = httpContext.Request.Host.Value;

    var prefix = httpContext.Request.Headers["X-Forwarded-Prefix"].FirstOrDefault();
    if (string.IsNullOrWhiteSpace(prefix))
        prefix = httpContext.Request.PathBase.Value ?? string.Empty;

    var address = $"{scheme}://{host}{prefix}{httpContext.Request.Path}";
    return Regex.Replace(wsdl, "(<soap(?:12)?:address\\s+location=\")[^\"]+(\")", match =>
        match.Groups[1].Value + XmlAttributeEscape(address) + match.Groups[2].Value);
}

static string? ExtractSoapOperationName(string payload)
{
    if (string.IsNullOrWhiteSpace(payload))
        return null;

    try
    {
        var document = XDocument.Parse(payload, LoadOptions.PreserveWhitespace);
        var body = document
            .Descendants()
            .FirstOrDefault(element =>
                string.Equals(element.Name.LocalName, "Body", StringComparison.OrdinalIgnoreCase) &&
                (element.Name.NamespaceName == "http://schemas.xmlsoap.org/soap/envelope/" ||
                 element.Name.NamespaceName == "http://www.w3.org/2003/05/soap-envelope"));

        return body?.Elements().FirstOrDefault()?.Name.LocalName;
    }
    catch
    {
        return null;
    }
}

static IResult BuildSoapAcceptedResponse(string operation)
{
    var responseName = operation + "Response";
    var resultName = operation + "Result";
    var message = "Recebido pelo Yeshua para processamento.";
    var dataRetorno = DateTimeOffset.UtcNow.ToString("O");
    var xml = string.Concat(
        "<?xml version=\"1.0\" encoding=\"utf-8\"?>",
        "<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\">",
        "<s:Body>",
        "<", responseName, " xmlns=\"http://tempuri.org/\">",
        "<", resultName, " xmlns:a=\"http://schemas.datacontract.org/2004/07/SGT.WebService\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\">",
        "<a:CodigoMensagem>0</a:CodigoMensagem>",
        "<a:DataRetorno>", XmlEscape(dataRetorno), "</a:DataRetorno>",
        "<a:Mensagem>", XmlEscape(message), "</a:Mensagem>",
        "<a:Objeto i:nil=\"true\" />",
        "<a:Status>true</a:Status>",
        "</", resultName, ">",
        "</", responseName, ">",
        "</s:Body>",
        "</s:Envelope>");

    return Results.Content(xml, "text/xml; charset=utf-8");
}

static IResult BuildSoapFault(string code, string message)
{
    var xml = string.Concat(
        "<?xml version=\"1.0\" encoding=\"utf-8\"?>",
        "<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\">",
        "<s:Body>",
        "<s:Fault>",
        "<faultcode>s:", XmlEscape(code), "</faultcode>",
        "<faultstring>", XmlEscape(message), "</faultstring>",
        "</s:Fault>",
        "</s:Body>",
        "</s:Envelope>");

    return Results.Content(xml, "text/xml; charset=utf-8", statusCode: StatusCodes.Status500InternalServerError);
}

static string XmlEscape(string value)
{
    return (value ?? string.Empty)
        .Replace("&", "&amp;")
        .Replace("<", "&lt;")
        .Replace(">", "&gt;")
        .Replace("\"", "&quot;")
        .Replace("'", "&apos;");
}

static string XmlAttributeEscape(string value)
{
    return XmlEscape(value);
}

}
